<?php
namespace App\Services\MasterData;
use App\Services\Audit\ActivityLogService; use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Facades\DB;
class MasterChangeService { public function __construct(private ActivityLogService $audit){} public function create(string $modelClass,array $data,string $module): Model { return DB::transaction(function() use($modelClass,$data,$module){$model=$modelClass::create($data);$this->audit->record($module,'create',$model,[], $model->fresh()->toArray());return $model;}); } public function update(Model $model,array $data,string $module): Model { return DB::transaction(function() use($model,$data,$module){$before=$model->toArray();$model->fill($data)->save();$after=$model->fresh()->toArray();$this->audit->record($module,'update',$model,$before,$after);return $model;}); } public function setActive(Model $model,bool $active,string $module): Model { return DB::transaction(function() use($model,$active,$module){$before=$model->toArray();$model->is_active=$active;$model->save();$this->audit->record($module,$active?'activate':'deactivate',$model,$before,$model->fresh()->toArray());return $model;}); } }
